I hunted this down to a super simple example now. It looks like this is due to the usage of `process` within styled-components:

``` js
// main.js
import foo from "./foo";

import("./import");

console.log('main', foo === 'bar');

// import.js
import foo from "./foo";

console.log('import', foo === 'bar');

// foo.js
process // this triggers the conversion to cjs

export default 'bar'
```

When running in the browser it will output
```
main true
import false
```

But should be
```
main true
import true
```
This is due to `foo` being an object in `import.js`.

Removing `process` resolves the issue.

Any idea why this is happening? :)

I have some findings on that:

When running parcel with `PARCEL_WORKERS=1` the build is passing.

In the example, page1 is working fine. It imports and uses react as following

```js
var $ea7b41558fa2f98$init = parcelRequire("80167699844891757ea7b41558fa2f98");
...
var $b8bc34563fd8293abd35d65d54d75$export$default = function Page1() {
  var $ea7b41558fa2f98$$interop$default = $parcel$interopDefault($ea7b41558fa2f98$init());
  return $ea7b41558fa2f98$$interop$default.createElement("div", null, "Page 1");
};
```

Where page2 looks as following
```js
var $ea7b41558fa2f98$exports = parcelRequire("80167699844891757ea7b41558fa2f98");
...
var $c302d056b50b4a5fdc682b4f5c4e00e$export$default = function Page2() {
  var $ea7b41558fa2f98$$interop$default = $parcel$interopDefault($ea7b41558fa2f98$exports);
  return $ea7b41558fa2f98$$interop$default.createElement("div", null, "Page 2");
};
```

So basically the init call is missing and therefore the function is passed to the `$parcel$interopDefault` function which for sure does not have an `__esModule` flag nor default export.

From what I understand some information in `asset.meta` is out of sync when running parcel with multiple workers. But this is more guessing.

Not sure where I could best search for those kind of issues. Any ideas or hints?
